#include <stdlib.h>
#include <string.h>
#include <omp.h>

#define MR 6
#define NR 16
#define KC 256
#define MC 96

typedef float v8f __attribute__((vector_size(32)));

static inline v8f ld8(const float *p) { v8f v; memcpy(&v, p, sizeof v); return v; }
static inline void st8(float *p, v8f v) { memcpy(p, &v, sizeof v); }

static void kernel(int kc, const float *restrict Ap, const float *restrict Bp,
                   float *restrict C, int ldc, int mr, int nr, int first)
{
    v8f c00 = {0}, c01 = {0}, c10 = {0}, c11 = {0}, c20 = {0}, c21 = {0};
    v8f c30 = {0}, c31 = {0}, c40 = {0}, c41 = {0}, c50 = {0}, c51 = {0};

    for (int k = 0; k < kc; k++) {
        v8f b0 = ld8(Bp + k * NR);
        v8f b1 = ld8(Bp + k * NR + 8);
        const float *a = Ap + k * MR;
        float a0 = a[0], a1 = a[1], a2 = a[2], a3 = a[3], a4 = a[4], a5 = a[5];
        c00 += a0 * b0; c01 += a0 * b1;
        c10 += a1 * b0; c11 += a1 * b1;
        c20 += a2 * b0; c21 += a2 * b1;
        c30 += a3 * b0; c31 += a3 * b1;
        c40 += a4 * b0; c41 += a4 * b1;
        c50 += a5 * b0; c51 += a5 * b1;
    }

    v8f acc[MR][2] = {{c00, c01}, {c10, c11}, {c20, c21},
                      {c30, c31}, {c40, c41}, {c50, c51}};

    if (mr == MR && nr == NR) {
        for (int r = 0; r < MR; r++) {
            float *cr = C + (size_t)r * ldc;
            if (first) {
                st8(cr, acc[r][0]);
                st8(cr + 8, acc[r][1]);
            } else {
                st8(cr, ld8(cr) + acc[r][0]);
                st8(cr + 8, ld8(cr + 8) + acc[r][1]);
            }
        }
    } else {
        float tmp[MR][NR];
        for (int r = 0; r < MR; r++) {
            st8(&tmp[r][0], acc[r][0]);
            st8(&tmp[r][8], acc[r][1]);
        }
        for (int r = 0; r < mr; r++) {
            float *cr = C + (size_t)r * ldc;
            if (first)
                for (int j = 0; j < nr; j++) cr[j] = tmp[r][j];
            else
                for (int j = 0; j < nr; j++) cr[j] += tmp[r][j];
        }
    }
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;
    int npanels = (n + NR - 1) / NR;
    size_t bsz = (size_t)KC * npanels * NR * sizeof(float);
    bsz = (bsz + 63) & ~(size_t)63;
    float *Bp = aligned_alloc(64, bsz);
    int nmblocks = (n + MC - 1) / MC;

    #pragma omp parallel
    {
        float *Ap = aligned_alloc(64, (size_t)MC * KC * sizeof(float));

        for (int k0 = 0; k0 < n; k0 += KC) {
            int kc = n - k0 < KC ? n - k0 : KC;
            int first = (k0 == 0);

            /* pack B[k0:k0+kc, :] into column panels of width NR */
            #pragma omp for schedule(static)
            for (int p = 0; p < npanels; p++) {
                int j0 = p * NR;
                int nr = n - j0 < NR ? n - j0 : NR;
                float *dst = Bp + (size_t)p * kc * NR;
                for (int k = 0; k < kc; k++) {
                    const float *src = B + (size_t)(k0 + k) * n + j0;
                    float *d = dst + k * NR;
                    if (nr == NR) {
                        memcpy(d, src, NR * sizeof(float));
                    } else {
                        int j = 0;
                        for (; j < nr; j++) d[j] = src[j];
                        for (; j < NR; j++) d[j] = 0.0f;
                    }
                }
            }
            /* implicit barrier */

            #pragma omp for schedule(dynamic, 1)
            for (int mb = 0; mb < nmblocks; mb++) {
                int i0 = mb * MC;
                int mc = n - i0 < MC ? n - i0 : MC;
                int nmicro = (mc + MR - 1) / MR;

                /* pack A[i0:i0+mc, k0:k0+kc] into row panels of height MR */
                for (int m = 0; m < nmicro; m++) {
                    float *dst = Ap + (size_t)m * kc * MR;
                    int ib = i0 + m * MR;
                    int mr = n - ib < MR ? n - ib : MR;
                    for (int r = 0; r < MR; r++) {
                        if (r < mr) {
                            const float *src = A + (size_t)(ib + r) * n + k0;
                            for (int k = 0; k < kc; k++) dst[k * MR + r] = src[k];
                        } else {
                            for (int k = 0; k < kc; k++) dst[k * MR + r] = 0.0f;
                        }
                    }
                }

                for (int p = 0; p < npanels; p++) {
                    int j0 = p * NR;
                    int nr = n - j0 < NR ? n - j0 : NR;
                    const float *bp = Bp + (size_t)p * kc * NR;
                    for (int m = 0; m < nmicro; m++) {
                        int ib = i0 + m * MR;
                        int mr = n - ib < MR ? n - ib : MR;
                        kernel(kc, Ap + (size_t)m * kc * MR, bp,
                               C + (size_t)ib * n + j0, n, mr, nr, first);
                    }
                }
            }
            /* implicit barrier before Bp is repacked */
        }

        free(Ap);
    }

    free(Bp);
}
